        try operation_headers.append(allocator, .{ .name = "Authorization", .value = auth_header.? });
    }

    return requestRawWithExtraHeaders(client, std.http.Method.POST, uri_buf.written(), payload, operation_headers.items);
}

pub fn loadModelResult(client: *Client, requestBody: contracts.LoadModelRequest) !ApiResult(contracts.LoadModelResponse) {
    return parseRawResponse(contracts.LoadModelResponse, try loadModelRaw(client, requestBody));
}

